package com.rohit.inventory.service;
import com.rohit.inventory.dto.request.LoginRequest; import com.rohit.inventory.dto.response.LoginResponse; import com.rohit.inventory.dto.response.UserResponse; import com.rohit.inventory.entity.User; import com.rohit.inventory.mapper.UserMapper; import com.rohit.inventory.repository.UserRepository; import com.rohit.inventory.security.InventoryUserDetailsService; import com.rohit.inventory.security.JwtService; import java.time.Instant; import org.springframework.security.authentication.AuthenticationManager; import org.springframework.security.authentication.BadCredentialsException; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.Authentication; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService { private final AuthenticationManager manager; private final UserRepository users; private final JwtService jwt; private final InventoryUserDetailsService details; private final UserMapper mapper; private final AuditService audit; public AuthService(AuthenticationManager manager,UserRepository users,JwtService jwt,InventoryUserDetailsService details,UserMapper mapper,AuditService audit){this.manager=manager;this.users=users;this.jwt=jwt;this.details=details;this.mapper=mapper;this.audit=audit;}
 @Transactional public LoginResponse login(LoginRequest request){ Authentication auth; try {auth=manager.authenticate(UsernamePasswordAuthenticationToken.unauthenticated(request.email().toLowerCase(),request.password()));} catch(Exception ex){throw new BadCredentialsException("Invalid credentials");} User user=users.findByEmail(request.email().toLowerCase()).orElseThrow(()->new BadCredentialsException("Invalid credentials")); user.setLastLoginAt(Instant.now()); UserDetails principal=details.toUserDetails(user); audit.record(user.getId(),"LOGIN_SUCCESS","USER",user.getId(),java.util.Map.of("email",user.getEmail())); return new LoginResponse(jwt.generate(user.getId(),user.getEmail(),principal.getAuthorities()),"Bearer",jwt.expirationSeconds(),mapper.toResponse(user)); }
 @Transactional(readOnly=true) public UserResponse me(String email){ return mapper.toResponse(users.findByEmail(email).orElseThrow(()->new BadCredentialsException("Invalid credentials"))); }
 @Transactional public void logout(String email){ User user=users.findByEmail(email).orElseThrow(()->new BadCredentialsException("Invalid credentials")); audit.record(user.getId(),"LOGOUT","USER",user.getId(),java.util.Map.of()); }
}
